import "@testing-library/jest-dom";
import "whatwg-fetch";
import { TextEncoder, TextDecoder } from "util";

// Node may not expose TextEncoder/TextDecoder in older runtimes; ensure they're available
if (typeof global.TextEncoder === "undefined")
  (global as any).TextEncoder = TextEncoder as any;
if (typeof global.TextDecoder === "undefined")
  (global as any).TextDecoder = TextDecoder as any;

import { jest, beforeAll, afterAll, afterEach } from "@jest/globals";
// Verify hook availability
console.log(
  "SETUP_TESTS: hooks -> beforeAll:",
  typeof beforeAll,
  "global.beforeAll:",
  typeof (globalThis as any).beforeAll
);
// Delay importing MSW until after early polyfills (setupFiles) run
let server: any;

declare global {
  var localStorage: Storage;
  var sessionStorage: Storage;
  var console: Console;
}

// Ensure fetch exists; if not, provide a Jest mock (MSW will set up an implementation)
if (!global.fetch) {
  global.fetch = jest.fn();
}

// MSW server lifecycle hooks
beforeAll(async () => {
  console.log("SETUP_TESTS: beforeAll start");
  // Ensure stream polyfills are available in this module scope before importing MSW
  try {
    const {
      TransformStream,
      ReadableStream,
      WritableStream,
    } = require("web-streams-polyfill");
    if (typeof global.TransformStream === "undefined")
      global.TransformStream = TransformStream;
    if (typeof global.ReadableStream === "undefined")
      global.ReadableStream = ReadableStream;
    if (typeof global.WritableStream === "undefined")
      global.WritableStream = WritableStream;
    if (typeof globalThis !== "undefined") {
      if (typeof globalThis.TransformStream === "undefined")
        globalThis.TransformStream = TransformStream;
    }
  } catch (e) {
    // ignore
  }

  // Dynamically import MSW (ESM) so the ESM loader handles its ESM-only deps
  try {
    const msw = await import("msw/node");
    console.log("SETUP_TESTS: imported msw/node");
    const handlersMod = await import("./mocks/handlers");
    console.log("SETUP_TESTS: imported handlers module", Object.keys(handlersMod));
    const { server: importedServer } = await import("./mocks/server");
    console.log("SETUP_TESTS: imported server module");
    // Support both the previous "handlers" export and the new async getter
    let handlers: any[] = [];
    if (typeof handlersMod.getHandlers === "function") {
      console.log("SETUP_TESTS: handlersMod.getHandlers is a function - invoking");
      handlers = await handlersMod.getHandlers();
      console.log("SETUP_TESTS: handlers resolved length=", handlers.length);
    } else {
      handlers = handlersMod.handlers || handlersMod.default || [];
      console.log("SETUP_TESTS: handlers from module (sync) length=", handlers.length);
    }
    // handlers loaded; register them on the server
    // Register handlers on the shared server and start it
    importedServer.use(...handlers);
    importedServer.listen();
    console.log("SETUP_TESTS: server.listen called and handlers registered");
    // keep a reference for cleanup helpers below
    server = importedServer;
  } catch (e) {
    console.error("setupTests beforeAll failed to initialize MSW:", e);
  }
});

afterEach(() => server && server.resetHandlers());
afterAll(() => server && server.close());

// Mock sessionStorage
const sessionStorageMock = {
  getItem: jest.fn(),
  setItem: jest.fn(),
  removeItem: jest.fn(),
  clear: jest.fn(),
  key: jest.fn(),
  length: 0,
};
global.sessionStorage = sessionStorageMock as unknown as Storage;

// Mock console methods to reduce noise in tests
global.console = {
  ...console,
  log: jest.fn(),
  debug: jest.fn(),
  info: jest.fn(),
  warn: jest.fn(),
  // keep errors visible so setup failures surface in CI and dev runs
  error: console.error,
};
